export function ruleAt(h, pos) {
    // The schema rule whose definition holds source offset pos: the definition
    // (N_RULE, at its name) with the largest offset <= pos; -1 if none.
    if (pos < 0) {
        return -1;
    }
    let best = -1;
    let at = -1;
    for (let r = 0; r < nrules(h); r++) {
        if (rw(h, r, 7) === 0) {
            let d = rw(h, r, 2);
            while (d >= 0) {
                const dp = npos(h, d);
                if ((dp <= pos) && (dp > at)) {
                    at = dp;
                    best = r;
                }
                d = defNext(h, d);
            }
        }
    }
    return best;
}

